t(slot)\n    return select(1, pcall(CC.Controller.triggerNormalSkillBySlotIndex, slot))\nend\n\nfunction CC.fireUltimate()\n    return select(1, pcall(CC.Controller.triggerUltimateSkill))\nend\n\nfunction CC.ultimateNameForPet(entry)\n    local petCfg = PetConfig[entry.configId]\n    local poolId = type(petCfg) == \"table\" and petCfg.skillPoolId\n    local pool = poolId and CC.SkillPoolConfig[poolId]\n    if type(pool) ~= \"table\" or type(pool.chargeSkillList) ~= \"table\" then return nil end\n    local level = tonumber(entry.level) or 1\n    local bestId, bestReq\n    for _, pair in ipairs(pool.chargeSkillList) do\n        local sid, req = pair[1], pair[2]\n        if type(sid) == \"number\" and type(req) == \"number\" then\n            if req <= level and (not bestReq or req >= bestReq) then\n                bestReq = req\n                bestId = sid\n            elseif not bestId then\n                bestId = sid\n            end\n        end\n    end\n    local cfg = bestId and CC.SkillConfig[bestId]\n    return type(cfg) == \"table\" and cfg.name or nil\nend\n\nfunction CC.tokenDisplay(entry, token)\n    if token == \"Ultimate\" then\n        local name = CC.ultimateNameForPet(entry)\n        return name and (\"Ult: \" .. name) or \"Ultimate\"\n    end\n    local slot = tonumber(token)\n    local s = slot and type(entry.skillList) == \"table\" and entry.skillList[slot]\n    local cfg = type(s) == \"table\" and CC.SkillConfig[s.configId]\n    return type(cfg) == \"table\" and cfg.name or (\"Skill \" .. tostring(token))\nend\n\nfunction CC.petSkillOptions(entry)\n    local values, map = {}, {}\n    local skillList = type(entry.skillList) == \"table\" and entry.skillList or {}\n    for i = 1, 3 do\n        local s = skillList[i]\n        if type(s) == \"table\" and s.configId then\n            local cfg = CC.SkillConfig[s.configId]\n            local name = type(cfg) == \"table\" and cfg.name or (\"Skill \" .. i)\n            local label = \"Skill \" .. i .. \" - \" .. name\n            table.insert(values, label)\n            map[label] = tostring(i)\n        end\n    end\n    local ultName = CC.ultimateNameForPet(entry)\n    local ultLabel = ultName and (\"Ultimate - \" .. ultName) or \"Ultimate\"\n    table.insert(values, ultLabel)\n    map[ultLabel] = \"Ultimate\"\n    return values, map\nend\n\nfunction CC.selectedPetEntry()\n    local uid = State.SelectedCombatPet and Shared.LeaderPetMap[State.SelectedCombatPet]\n    local entry = uid and PetStorage.getPetList()[uid]\n    return entry, uid\nend\n\nfunction CC.updateOrderLabel()\n    if not CC.orderLabel then return end\n    if #CC.buildingOrder == 0 then\n        CC.orderLabel:SetText(\"Rotation: (empty)\")\n        return\n    end\n    local entry = CC.selectedPetEntry()\n    local parts = {}\n    for i, token in ipairs(CC.buildingOrder) do\n        parts[i] = i .. \". \" .. (entry and CC.tokenDisplay(entry, token) or token)\n    end\n    CC.orderLabel:SetText(\"Rotation: \" .. table.concat(parts, \"   \"))\nend\n\nfunction CC.refreshSkillDropdown()\n    local entry = CC.selectedPetEntry()\n    if not entry then\n        CC.skillMap = {}\n        if Options.CombatSkill then Options.CombatSkill:SetValues({}) end\n        return\n    end\n    local values, map = CC.petSkillOptions(entry)\n    CC.skillMap = map\n    if Options.CombatSkill then\n        Options.CombatSkill:SetValues(values)\n        if values[1] then Options.CombatSkill:SetValue(values[1]) end\n    end\nend\n\nfunction CC.handleCustomAutoBattle()\n    if not State.EnableCustomAutoBattle then return end\n    if not CC.Controller.getCanOperate() then return end\n    local data = getBattleData()\n    if not data then return end\n    local selfPet = CC.Controller.getLocalCurrentSelfPet(data)\n    if type(selfPet) ~= \"table\" or type(selfPet.skills) ~= \"table\" then return end\n\n    local uid = tostring(selfPet.uid)\n    local order = State.CustomSkillOrders[selfPet.configId]\n    if type(order) ~= \"table\" or #order == 0 then order = CC.DEFAULT_ORDER end\n    if not CustomSkillOrderIndexes[uid] then CustomSkillOrderIndexes[uid] = 1 end\n\n    local function tryToken(token)\n        if token == \"Ultimate\" then\n            if CC.isSkillUsable(CC.ultimateSkill(selfPet)) then return CC.fireUltimate() end\n        else\n            local slot = tonumber(token)\n            if slot and CC.isSkillUsable(CC.skillBySlot(selfPet, slot)) then return CC.fireSlot(slot) end\n        end\n        return false\n    end\n\n    local count = #order\n    for _ = 1, count do\n        local idx = CustomSkillOrderIndexes[uid]\n        local token = order[idx] or order[1]\n        CustomSkillOrderIndexes[uid] = (idx % count) + 1\n        if tryToken(token) then return end\n    end\n\n    for slot = 1, 3 do\n        if CC.isSkillUsable(CC.skillBySlot(selfPet, slot)) and CC.fireSlot(slot) then return end\n    end\n    if CC.isSkillUsable(CC.ultimateSkill(selfPet)) then CC.fireUltimate() end\nend\n\ntask.spawn(function()\n    while Shared.Running do\n        if State.EnableCustomAutoBattle and getCurrentBattle() then\n            pcall(CC.handleCustomAutoBattle)\n        end\n        task.wait(0.3)\n    end\nend)\n\nlocal TeamLabels = {}\n\nlocal function updateTeamLabels()\n    local pg = PetGroupStorage.getPetGroup()\n    local petsData = {}\n\n    if type(pg) == \"table\" and type(pg.petGroupList) == \"table\" then\n        local currentTeam = pg.petGroupList[pg.currentGroupId or pg.currentPetGroupIndex]\n        if type(currentTeam) == \"table\" and type(currentTeam.petUuids) == \"table\" then\n            for i = 1, 5 do\n                local uid = currentTeam.petUuids[i]\n                if uid then\n                    local pet = PetStorage.getPetList()[uid]\n                    if type(pet) == \"table\" then\n                        local pName = petName(pet.configId)\n                        local lvl = pet.level or \"?\"\n                        local order = State.CustomSkillOrders[pet.configId]\n                        local orderStr\n                        if order and #order > 0 then\n                            local parts = {}\n                            for j, token in ipairs(order) do\n                                parts[j] = CC.tokenDisplay(pet, token)\n                            end\n                            orderStr = table.concat(parts, \", \")\n                        else\n                            orderStr = \"None\"\n                        end\n                        petsData[i] = i .. \". \" .. pName .. \" L\" .. lvl .. \" | \" .. orderStr\n                    end\n                end\n            end\n        end\n    end\n\n    for i = 1, 5 do\n        if TeamLabels[i] then\n            TeamLabels[i]:SetText(petsData[i] or (i .. \". (Empty)\"))\n        end\n    end\nend\n\nlocal function buildTeamDropdown()\n    local pg = PetGroupStorage.getPetGroup()\n    local list = {}\n    if type(pg) == \"table\" and type(pg.petGroupList) == \"table\" then\n        for i, _ in pairs(pg.petGroupList) do\n            table.insert(list, \"Team \" .. i)\n        end\n    end\n    return list\nend\n\nlocal CustomCombatBox = Tabs.Combat:AddLeftGroupbox(\"Skill Rotation\")\n\nfor i = 1, 5 do\n    TeamLabels[i] = CustomCombatBox:AddLabel(i .. \". (Empty)\")\nend\nupdateTeamLabels()\n\nCustomCombatBox:AddButton({\n    Text = \"Detect Team\",\n    Tooltip = \"Refreshes current team, pet list, team list, and available skills.\",\n    Func = function()\n        updateTeamLabels()\n        local labels, map = Shared.BuildPetEntries()\n        Shared.LeaderPetMap = map\n        Options.CombatSelectPet:SetValues(labels)\n        Options.CombatSwitchTeam:SetValues(buildTeamDropdown())\n        CC.refreshSkillDropdown()\n        Library:Notify(\"Team data refreshed.\", 3)\n    end,\n})\n\nCustomCombatBox:AddDropdown(\"CombatSelectPet\", {\n    Text = \"Select Pet\",\n    Tooltip = \"Pet whose skill rotation you are editing.\",\n    Values = Shared.BuildPetEntries(),\n    AllowNull = true,\n    Searchable = true,\n    Callback = function(value)\n        State.SelectedCombatPet = value\n        CC.buildingOrder = {}\n        CC.refreshSkillDropdown()\n        CC.updateOrderLabel()\n    end,\n})\n\nCustomCombatBox:AddDropdown(\"CombatSkill\", {\n    Text = \"Skill\",\n    Tooltip = \"Skill to append to the selected pet's custom rotation.\",\n    Values = {},\n    AllowNull = true,\n    Callback = function(value)\n        State.SelectedCombatSkill = value\n    end,\n})\n\nCC.orderLabel = CustomCombatBox:AddLabel(\"Rotation: (empty)\")\n\nCustomCombatBox:AddButton({\n    Text = \"Add to Rotation\",\n    Tooltip = \"Adds the selected skill to the end of the rotation preview.\",\n    Func = function()\n        local token = State.SelectedCombatSkill and CC.skillMap[State.SelectedCombatSkill]\n        if not token then\n            Library:Notify(\"Select a pet and skill first.\", 3)\n            return\n        end\n        table.insert(CC.buildingOrder, token)\n        CC.updateOrderLabel()\n    end,\n})\n\nCustomCombatBox:AddButton({\n    Text = \"Remove Last\",\n    Tooltip = \"Removes the last skill from the rotation preview.\",\n    Func = function()\n        table.remove(CC.buildingOrder)\n        CC.updateOrderLabel()\n        Library:Notify(\"Removed last rotation skill.\", 2)\n    end,\n})\n\nCustomCombatBox:AddButton({\n    Text = \"Clear Rotation\",\n    Tooltip = \"Clears the current rotation preview before applying.\",\n    Func = function()\n        CC.buildingOrder = {}\n        CC.updateOrderLabel()\n        Library:Notify(\"Rotation preview cleared.\", 2)\n    end,\n})\n\nCustomCombatBox:AddButton({\n    Text = \"Apply to Pet\",\n    Tooltip = \"Saves the current rotation preview for the selected pet species.\",\n    Func = function()\n        local entry, uid = CC.selectedPetEntry()\n        if not entry then\n            Library:Notify(\"Select a pet first.\", 3)\n            return\n        end\n        local clone = {}\n        for _, token in ipairs(CC.buildingOrder) do table.insert(clone, token) end\n        State.CustomSkillOrders[entry.configId] = clone\n        if uid then CustomSkillOrderIndexes[uid] = 1 end\n        Library:Notify(\"Saved rotation for \" .. petName(entry.configId) .. \".\", 3)\n        updateTeamLabels()\n    end,\n})\n\nCustomCombatBox:AddButton({\n    Text = \"Clear All Pets\",\n    Tooltip = \"Removes all custom skill rotations from every pet.\",\n    Func = function()\n        State.CustomSkillOrders = {}\n        CustomSkillOrderIndexes = {}\n        Library:Notify(\"Cleared all custom skill rotations.\")\n        updateTeamLabels()\n    end,\n})\n\nlocal TeamSwitchBox = Tabs.Combat:AddLeftGroupbox(\"Switch Team\")\nTeamSwitchBox:AddDropdown(\"CombatSwitchTeam\", {\n    Text = \"Team\",\n    Tooltip = \"Team to switch to when pressing Switch Now.\",\n    Values = buildTeamDropdown(),\n    AllowNull = true,\n    Callback = function(value)\n        State.SelectedSwitchTeam = value\n    end,\n})\nTeamSwitchBox:AddButton({\n    Text = \"Switch Now\",\n    Tooltip = \"Switches the active pet group to the selected team.\",\n    Func = function()\n        if not State.SelectedSwitchTeam then return end\n        local idx = tonumber(State.SelectedSwitchTeam:match(\"%d+\"))\n        if idx then\n            pcall(PetGroupService.reqSwitchCurrentPetGroup, idx)\n            task.wait(0.5)\n            updateTeamLabels()\n            Library:Notify(\"Switched to Team \" .. idx, 3)\n        end\n    end,\n})\n\nlocal CombatAutoBox = Tabs.Combat:AddRightGroupbox(\"Custom Auto Battle\")\nCombatAutoBox:AddToggle(\"EnableCustomAutoBattle\", {\n    Text = \"Enable Custom Auto Battle\",\n    Tooltip = \"Uses saved skill rotations while Auto Battle is active.\",\n    Default = false,\n    Callback = function(value)\n        State.EnableCustomAutoBattle = value\n        if State.AutoBattle and getCurrentBattle() then\n            turnAutoBattle(true)\n        end\n        notifyToggle(\"Custom Auto Battle\", value)\n    end,\n})\n",
